  ahora: 'imprimir(ahora() > 1700000000000.0)',
  reloj: 'var t0 = reloj()\npara i en rango(1000) { }\nimprimir(reloj() - t0 >= 0.0)',
  memoria: 'var xs: lista<entero> = rango(1000)\nvar m = memoria()\nimprimir(claves(m))',
  recolectar: 'var xs: lista<entero> = rango(5000)\nxs = []\nrecolectar()\nimprimir(memoria()["objetos"] < 5000)',
  instrucciones: 'para i en rango(100) { }\nimprimir(instrucciones() > 100)',

