  'probar.antesDeTodo': 'usar probar, antesDeTodo, correrPruebas, debeSer de "probar"\nantesDeTodo(fn() { imprimir("preparando") })\nprobar("una", fn() { debeSer(1, 1) })\ncorrerPruebas()',
