  'probar.antesDeCada': 'usar probar, antesDeCada, correrPruebas, debeSer de "probar"\nvar n: entero = 0\nantesDeCada(fn() { n = n + 1 })\nprobar("una", fn() { debeSer(n, 1) })\nprobar("dos", fn() { debeSer(n, 2) })\ncorrerPruebas()',
  'probar.despuesDeCada': 'usar probar, despuesDeCada, correrPruebas, debeSer de "probar"\ndespuesDeCada(fn() { imprimir("  (limpiando)") })\nprobar("una", fn() { debeSer(1, 1) })\ncorrerPruebas()',
  'probar.debeSer': 'usar debeSer, debeFallar de "probar"\ndebeSer([1, [2, 3]], [1, [2, 3]])\nimprimir("compara en profundidad · y si falla dice: " + debeFallar(fn() { debeSer(4, 5) }))',
  'probar.noDebeSer': 'usar noDebeSer, debeFallar de "probar"\nnoDebeSer([1, 2], [2, 1])\nimprimir(debeFallar(fn() { noDebeSer(4, 4) }))',
  'probar.debeSerCierto': 'usar debeSerCierto, debeFallar de "probar"\ndebeSerCierto("algo")\nimprimir(debeFallar(fn() { debeSerCierto([]) }))',
  'probar.debeSerFalso': 'usar debeSerFalso, debeFallar de "probar"\ndebeSerFalso(0)\nimprimir(debeFallar(fn() { debeSerFalso(1) }))',
  'probar.debeSerCerca': 'usar debeSerCerca, debeFallar de "probar"\ndebeSerCerca(0.1 + 0.2, 0.3)\nimprimir(debeFallar(fn() { debeSerCerca(1.0, 1.5) }))',
  'probar.debeSerMayor': 'usar debeSerMayor, debeFallar de "probar"\ndebeSerMayor(3, 2)\nimprimir(debeFallar(fn() { debeSerMayor(2, 3) }))',
  'probar.debeSerMenor': 'usar debeSerMenor, debeFallar de "probar"\ndebeSerMenor(2, 3)\nimprimir(debeFallar(fn() { debeSerMenor(3, 2) }))',
  'probar.debeSerAlMenos': 'usar debeSerAlMenos, debeFallar de "probar"\ndebeSerAlMenos(3, 3)\nimprimir(debeFallar(fn() { debeSerAlMenos(2, 3) }))',
  'probar.debeSerComoMucho': 'usar debeSerComoMucho, debeFallar de "probar"\ndebeSerComoMucho(3, 3)\nimprimir(debeFallar(fn() { debeSerComoMucho(4, 3) }))',
  'probar.debeContener': 'usar debeContener, debeFallar de "probar"\ndebeContener("hola mundo", "mundo")\ndebeContener([1, 2, 3], 2)\nimprimir(debeFallar(fn() { debeContener([1], 9) }))',
  'probar.noDebeContener': 'usar noDebeContener, debeFallar de "probar"\nnoDebeContener([1, 2], 9)\nimprimir(debeFallar(fn() { noDebeContener([1, 2], 1) }))',
  'probar.debeEmpezarCon': 'usar debeEmpezarCon, debeFallar de "probar"\ndebeEmpezarCon("hola", "ho")\nimprimir(debeFallar(fn() { debeEmpezarCon("hola", "la") }))',
  'probar.debeTerminarCon': 'usar debeTerminarCon, debeFallar de "probar"\ndebeTerminarCon("hola", "la")\nimprimir(debeFallar(fn() { debeTerminarCon("hola", "ho") }))',
  'probar.debeEstarVacio': 'usar debeEstarVacio, debeFallar de "probar"\ndebeEstarVacio([])\nimprimir(debeFallar(fn() { debeEstarVacio([1]) }))',
  'probar.debeTener': 'usar debeTener, debeFallar de "probar"\ndebeTener([1, 2, 3], 3)\nimprimir(debeFallar(fn() { debeTener([1], 3) }))',
  'probar.debeSerTipo': 'usar debeSerTipo, debeFallar de "probar"\ndebeSerTipo(1.5, "real")\nimprimir(debeFallar(fn() { debeSerTipo("a", "entero") }))',
  'probar.debeFallar': 'usar debeFallar de "probar"\nimprimir(debeFallar(fn() { imprimir(1 // 0) }))',
  'probar.noDebeFallar': 'usar noDebeFallar, debeFallar de "probar"\nnoDebeFallar(fn() { var x: entero = 1 + 1 })\nimprimir(debeFallar(fn() { noDebeFallar(fn() { lanzar "no" }) }))',
  'probar.debeFallarCon': 'usar debeFallarCon, debeFallar de "probar"\ndebeFallarCon(fn() { imprimir(1 // 0) }, "división entre cero")\nimprimir(debeFallar(fn() { debeFallarCon(fn() { lanzar "otra" }, "esta") }))',
  'probar.espia': 'usar espia, vecesLlamada de "probar"\nvar doble: funcion = espia(fn(x: entero): entero { devolver x * 2 })\nimprimir(doble(4), doble(5), vecesLlamada(doble))',
  'probar.llamadasDe': 'usar espia, llamadasDe de "probar"\nvar f: funcion = espia(fn(x: entero): entero { devolver x + 1 })\nimprimir(mapear([1, 2, 3], f))\nimprimir(llamadasDe(f))',
  'probar.vecesLlamada': 'usar espia, vecesLlamada de "probar"\nvar f: funcion = espia(fn(x: entero): entero { devolver x })\nf(1)\nf(2)\nimprimir(vecesLlamada(f))',
  'probar.correrPruebas': 'usar probar, correrPruebas, debeSer de "probar"\nprobar("pasa", fn() { debeSer(1, 1) })\nprobar("falla", fn() { debeSer(1, 2) })\nvar r: dic = correrPruebas()\nimprimir(r)',
  'probar.resumenPruebas': 'usar probar, correrPruebas, resumenPruebas, debeSer de "probar"\nprobar("pasa", fn() { debeSer(1, 1) })\nprobar("falla", fn() { debeSer(1, 2) })\ncorrerPruebas()\nimprimir("")\nimprimir(resumenPruebas())',
  'probar.soloFallos': 'usar probar, soloFallos, correrPruebas, debeSer de "probar"\nsoloFallos(cierto)\nprobar("esta pasa y no se imprime", fn() { debeSer(1, 1) })\nprobar("esta falla y sí", fn() { debeSer(1, 2) })\ncorrerPruebas()',
  'probar.semillaPruebas': 'usar probar, semillaPruebas, correrPruebas, debeSer de "probar"\nsemillaPruebas(7)\nprobar("a", fn() { debeSer(1, 1) })\nprobar("b", fn() { debeSer(2, 2) })\nprobar("c", fn() { debeSer(3, 3) })\ncorrerPruebas()',
