  'texto.envolver': 'usar envolver de "texto"\npara l en envolver("El ñandú corría por la pampa mientras el sol caía despacio.", 30) {\n    imprimir("|" + l)\n}',
  'texto.sangrar': 'usar sangrar de "texto"\nimprimir(sangrar("uno\\ndos", 4))',
