  'texto.sinAcentos': 'usar sinAcentos de "texto"\nimprimir(sinAcentos("Martín Núñez"))\nimprimir("la ñ se queda: en español es una letra")',
  'texto.igualSinAcentos': 'usar igualSinAcentos de "texto"\nimprimir(igualSinAcentos("Martín", "martin"))\nimprimir("pero año y ano son distintos:", igualSinAcentos("año", "ano"))',
  'texto.ordenAlfabetico': 'usar ordenAlfabetico, unir de "texto"\nvar ps: lista = ["ñandú", "nube", "nada", "ñu", "oso", "el", "él"]\nimprimir("por códigos:", unir(ordenar(ps), " "))\nimprimir("en español: ", unir(ordenAlfabetico(ps), " "))',
