  'texto.plantilla': 'usar plantilla de "texto"\n# Las llaves se escapan: en un texto escrito aquí son la interpolación del lenguaje.\nimprimir(plantilla("Hola \\{nombre\\}, debes \\{monto\\}", {"nombre": "Ana", "monto": 500}))',
