  'numerico.enteros': 'usar enteros, semilla, aListaA de "numerico"\nsemilla(7)\nimprimir(aListaA(enteros(8, 1, 7)), "— ocho dados")',
  'numerico.barajarJuntos': 'usar arreglo, barajarJuntos, semilla, aListaA de "numerico"\n# Los baraja con el MISMO orden: datos y etiquetas sin desparejarse. Hacerlo\n# con dos «barajar» es el fallo silencioso clásico.\nsemilla(3)\nfijo r = barajarJuntos(arreglo([1, 2, 3, 4]), arreglo([10, 20, 30, 40]))\nimprimir(aListaA(r[0]))\nimprimir(aListaA(r[1]))',
